contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, address payable recipient) public payable {
        require(address(this).balance >= amount);
        // Only the owner can call withdrawAll; this test contract must be the owner.
        require(c.owner() == address(this));
        require(recipient != c.owner());
        require(amount <= address(c).balance + amount); // amount is any uint
        // fund c with `amount` via its payable fallback (top-level statement)
        address(c).call{value: amount}("");
        uint cBalBefore = address(c).balance;
        uint recipBefore = recipient.balance;
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        assert(reverted || (recipient.balance == recipBefore + cBalBefore && address(c).balance == 0));
    }
    receive() external payable {}
}

